<?php declare(strict_types=1); require_once __DIR__.'/../config/bootstrap.php'; $error=null; if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf($_POST['_csrf']??null)){$error='Invalid security token.';}else{$email=strtolower(trim($_POST['email']??''));$password=$_POST['password']??'';$s=db()->prepare('SELECT * FROM admins WHERE email=:email LIMIT 1');$s->execute([':email'=>$email]);$admin=$s->fetch();if($admin&&password_verify($password,$admin['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=$admin['id'];header('Location:/admin/');exit;}$error='Invalid credentials.';}} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Login</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><main><section class="section"><div class="glass-panel"><p class="eyebrow">ADMIN</p><h1>Sign in</h1><?php if($error): ?><p><?=e($error)?></p><?php endif; ?><form method="post" class="contact-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="email" name="email" placeholder="Email" required><input type="password" name="password" placeholder="Password" required><button class="button button--primary">Sign in</button></form></div></section></main></body></html>